import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"CPU 型与 I/O 型","description":"","frontmatter":{"title":"CPU 型与 I/O 型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpu-vs-io-bound.md","filePath":"cs/cpu-vs-io-bound.md","lastUpdated":1789023840000}'),h={name:"cs/cpu-vs-io-bound.md"};function u(E,a,P,m,C,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="cpu-型与-i-o-型" tabindex="-1">CPU 型与 I/O 型 <a class="header-anchor" href="#cpu-型与-i-o-型" aria-label="Permalink to &quot;CPU 型与 I/O 型&quot;">​</a></h1><div class="epigraph"><p>作业交替着 CPU 突发与 I/O 突发；偏计算的长突发与偏等待设备的短突发，在同一套指标下要的调度完全不同。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/scheduling-metrics">上一课</a>定义了利用率、吞吐、周转、等待、响应与公平，还没有说就绪队列里的人长什么样。缺口是把线程分成<strong>CPU 型</strong>与 <strong>I/O 型</strong>：前者一次占满量子，后者很快自己睡去等设备。<a href="/cs/interrupt-bottom-half">中断下半部</a>唤醒的，多半是 I/O 型。本课只钉这种突发结构，不选 FCFS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若调度器把所有人当成永远可跑的计算，I/O 型难得 CPU，设备空闲，利用率反而下降——上一课已点过 I/O 与 CPU 交替能提高利用率，这里收成类型。CPU 型饿死 I/O 型会同时搞坏响应（交互）与利用率（磁盘停转）。缺口不是新的 PCB 字段名，而是用突发长度解释「为什么短作业要插队」。</p><p><span class="marginnote">类型会变：编译开始是 CPU 型，一等头文件磁盘就变成 I/O 型。调度器往往用最近一次突发长度来估计下一次，而不是看进程标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把执行画成 CPU 突发—阻塞—CPU 突发。I/O 型：短 CPU 突发，频繁进入阻塞。CPU 型：长突发，少阻塞。评价策略时用同一组<a href="/cs/scheduling-metrics">调度指标</a>，但作业混合必须声明。本课不引入多级队列，只要求后课策略能说出对两类人的偏向。</p>',8)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IO%5B%22I%2FO%20%E5%9E%8B%3A%20%E7%9F%AD%E7%AA%81%E5%8F%91%E5%90%8E%E9%98%BB%E5%A1%9E%22%5D%20--%3E%20DEV%5B%22%E7%AD%89%E8%AE%BE%E5%A4%87%22%5D%0A%20%20CPU%5B%22CPU%20%E5%9E%8B%3A%20%E9%95%BF%E7%AA%81%E5%8F%91%22%5D%20--%3E%20HOLD%5B%22%E5%8D%A0%E7%9D%80%20CPU%22%5D%0A%20%20DEV%20--%3E%20WAKE%5B%22%E4%B8%8B%E5%8D%8A%E9%83%A8%E5%94%A4%E9%86%92%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>idle 不是 I/O 型：它不等设备完成一项用户工作，只是队列空。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型把「公平」说清楚：给 I/O 型及时的短量子，它很快让出，CPU 型仍能得到大批时间，响应与利用率可兼得。纯 FCFS 让先到的 CPU 型挡住后面一串 I/O 型，传送带效应下一课会落到具体算法。唤醒只是把 I/O 型放回就绪，<strong>不</strong>保证马上跑——那是调度器的事。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 计算当成第三种突发类型写进主干。也不把「交互性启发式」的具体睡眠补偿公式当定义。实时任务按期限分类，不按 CPU/I/O 二分。</p><p>后课默认：就绪者带着不同的突发长度。这些就绪者在内核里挂成什么结构，下一课讲运行队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPU 型长突发，I/O 型短突发后阻塞；类型可随时间变。</li><li>亏待 I/O 型会同时损害响应与利用率。</li><li>就绪集合的数据结构是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const O=s(h,[["render",u]]);export{I as __pageData,O as default};
